import pytest

from conftest import make_modules_checkout
from xewe.cli import main
from xewe.env.project import Paths
from xewe.modules import registry as modules
from xewe.modules.registry import Registry
from xewe.report import XeWeError

MODULES_H = """\
// Generated by xewe modules generate; do not edit. Re-run ./setup.sh or `xewe modules select` to change modules.
// Included by the sketch after `os`; modules are declared in dependency order.
#pragma once

#include <XeWeModules.h>

Wifi wifi(os);
Time time_module(os, wifi);
Scheduler scheduler(os, time_module);
WebInterface web_interface(os, wifi);
"""

XEWE_MODULES_H = """\
// Generated by xewe modules generate; do not edit. The selected XeWe OS modules in dependency order.
#pragma once

#include "Wifi/Wifi.h"
#include "Time/Time.h"
#include "Scheduler/Scheduler.h"
#include "WebInterface/WebInterface.h"
"""

LIBRARY_PROPERTIES = """\
name=XeWeModules
version=v1.0.0
author=xewe-labs
maintainer=xewe-labs
sentence=The XeWe OS modules selected for this project; generated by xewe modules generate, do not edit.
paragraph=Modules: wifi, web-interface.
category=Other
url=https://github.com/xewe-labs/xewe-os-modules
architectures=esp32
depends=XeWeCore
includes=XeWeModules.h
"""
LOCK_HEADER = "# generated by xewe: slug|folder|source|ref|commit\n"


@pytest.fixture(params=["modules", "legacy"])
def checkout(request: pytest.FixtureRequest, tmp_path: Path) -> Path:
    return make_modules_checkout(tmp_path / "checkout", request.param)


def _set(checkout: Path, slug: str, key: str, value: str | None) -> None:
    props = next(checkout.rglob(f"*{slug}/module.properties"))
    lines = [ln for ln in props.read_text().splitlines() if not ln.startswith(f"{key}=")]
    if value is not None:
        lines.insert(0, f"{key}={value}")
    props.write_text("\n".join(lines) + "\n")


def test_registry_reads_both_layouts(checkout: Path) -> None:
    reg = Registry.load(checkout)
    assert reg.slugs() == ["buttons", "pins", "scheduler", "time", "web-interface", "wifi"]


def test_properties_first_key_wins() -> None:
    props, keys = modules.parse_properties("a=1\na=2\nb=x=y\n# c=3\n")
    assert props == {"a": "1", "b": "x=y"} and keys == ["a", "a", "b"]


def test_resolve_order_and_additions(checkout: Path, caplog: pytest.LogCaptureFixture) -> None:
    with caplog.at_level(logging.INFO, logger="xewe"):
        order = Registry.load(checkout).resolve(["scheduler", "web-interface"])
    assert [m.slug for m in order] == ["wifi", "time", "scheduler", "web-interface"]
    assert "scheduler requires time; adding it" in caplog.text
    assert "time requires wifi; adding it" in caplog.text
    assert modules.render_modules_h(order) == MODULES_H
    assert modules.render_library_h(order) == XEWE_MODULES_H


def test_cycle_is_an_error(checkout: Path) -> None:
    _set(checkout, "wifi", "depends_modules", "scheduler")
    with pytest.raises(XeWeError, match="dependency cycle through module"):
        Registry.load(checkout).resolve(["scheduler"])


def test_unknown_module_is_usage_error(checkout: Path) -> None:
    with pytest.raises(XeWeError) as exc:
        Registry.load(checkout).resolve(["nope"])
    assert exc.value.code == 2


def test_generate_writes_modules(tmp_path: Path, checkout: Path) -> None:
    p = Paths(tmp_path / "proj")
    order = modules.generate(p, Registry.load(checkout), ["wifi", "web-interface"], "https://x/mods", "v1.0.0", "c0ffee")
    assert [m.slug for m in order] == ["wifi", "web-interface"]
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    assert sorted(f.name for f in (p.modules / "src").iterdir()) == ["WebInterface", "Wifi", "XeWeModules.h"]
    assert (p.modules / "src" / "Wifi" / "Wifi.h").is_file()
    assert (p.modules / "library.properties").read_text() == LIBRARY_PROPERTIES
    assert (p.modules / "src" / "XeWeModules.h").read_text().endswith(
        '#include "Wifi/Wifi.h"\n#include "WebInterface/WebInterface.h"\n')
    text = p.src_modules_h.read_text()
    assert text.startswith("// Generated by xewe modules generate; do not edit.")
    assert text.endswith("#include <XeWeModules.h>\n\nWifi wifi(os);\nWebInterface web_interface(os, wifi);\n")
    assert p.modules_lock.read_text() == (
        LOCK_HEADER
        + "wifi|Wifi|https://x/mods|v1.0.0|c0ffee\n"
        "web-interface|WebInterface|https://x/mods|v1.0.0|c0ffee\n"
    )
    assert p.modules_lock == p.root / "build" / "modules" / "modules.lock"
    assert sorted(f.name for f in p.root.iterdir()) == ["build", "src"]
    assert sorted(f.name for f in (p.root / "src").iterdir()) == ["Modules.h"]  # no src/modules/ any more
    assert sorted(f.name for f in p.build.iterdir()) == ["modules"]  # staging swapped away, build/tmp removed


def test_library_version_falls_back_to_commit(tmp_path: Path, checkout: Path) -> None:
    p = Paths(tmp_path / "proj")
    modules.generate(p, Registry.load(checkout), ["wifi"], "local:/x", "-", "c0ffee")
    assert "\nversion=c0ffee\n" in (p.modules / "library.properties").read_text()


def test_generate_empty_selection(tmp_path: Path, checkout: Path) -> None:
    p = Paths(tmp_path / "proj")
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert modules.generate(p, Registry.load(checkout), [], "https://x/mods", "v1.0.0", "c0ffee") == []
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    assert sorted(f.name for f in (p.modules / "src").iterdir()) == ["XeWeModules.h"]
    props = (p.modules / "library.properties").read_text()
    assert "name=XeWeModules\n" in props and "paragraph=Modules: none.\n" in props
    lib_h = (p.modules / "src" / "XeWeModules.h").read_text()
    assert "#pragma once\n" in lib_h and "#include" not in lib_h
    text = p.src_modules_h.read_text()
    assert text.startswith("// Generated by xewe modules generate") and "#pragma once\n" in text
    assert "#include <XeWeModules.h>\n" in text and text.count("#include") == 1 and "(os" not in text
    assert p.modules_lock.read_text() == LOCK_HEADER


def test_generate_copies_module_tests(tmp_path: Path) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules", board_tests=True)
    wifi = checkout / "modules" / "wifi" / "tests"
    (wifi / "unit").mkdir()
    (wifi / "unit" / "test_logic.py").write_text("")
    (wifi / "board" / "__pycache__").mkdir()
    p = Paths(tmp_path / "proj")
    modules.generate(p, Registry.load(checkout), ["web-interface"], "s", "r", "c")  # wifi comes as a dependency
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src", "tests"]
    assert sorted(f.name for f in (p.modules / "tests").iterdir()) == ["web-interface", "wifi"]
    assert sorted(f.name for f in p.module_tests("wifi").iterdir()) == ["board", "unit"]
    assert sorted(f.name for f in (p.module_tests("wifi") / "board").iterdir()) == ["test_wifi.py"]
    assert (p.module_tests("web-interface") / "board" / "test_web-interface.py").is_file()
    # a new selection replaces the tests too
    modules.generate(p, Registry.load(checkout), ["pins"], "s", "r", "c")
    assert sorted(f.name for f in (p.modules / "tests").iterdir()) == ["pins"]


def test_module_dir_in_repo_and_from_project_copy(project: Paths, tmp_path: Path) -> None:
    from xewe.testing import module_dir

    wifi = tmp_path / "modules-src" / "modules" / "wifi"  # the recorded checkout (XEWE_MODULES_SOURCE)
    assert module_dir(wifi / "tests" / "unit" / "test_wifi.py") == wifi
    copy = project.module_tests("wifi") / "unit" / "test_wifi.py"
    copy.parent.mkdir(parents=True, exist_ok=True)
    copy.write_text("")
    assert module_dir(copy) == wifi


def test_generate_removes_previous_layout(tmp_path: Path, checkout: Path, capsys: pytest.CaptureFixture[str]) -> None:
    p = Paths(tmp_path / "proj")
    (p.build / "modules-lib" / "src").mkdir(parents=True)
    (p.build / "modules" / "modules").mkdir(parents=True)  # the old in-project modules checkout
    p.config_dir.mkdir()
    (p.config_dir / "modules.lock").write_text(LOCK_HEADER)
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert sorted(f.name for f in p.build.iterdir()) == ["config", "modules"]
    assert list(p.config_dir.iterdir()) == []
    assert sorted(f.name for f in p.modules.iterdir()) == ["library.properties", "modules.lock", "src"]
    out = capsys.readouterr().out
    assert "removed legacy build/modules-lib" in out and "removed legacy build/config/modules.lock" in out


def test_generate_removes_legacy_src_modules(tmp_path: Path, checkout: Path, capsys: pytest.CaptureFixture[str]) -> None:
    p = Paths(tmp_path / "proj")
    legacy = p.root / "src" / "modules"
    (legacy / "Wifi").mkdir(parents=True)
    (legacy / "Modules.h").write_text("// old\n")
    (legacy / "modules.lock").write_text(LOCK_HEADER + "wifi|Wifi|s|r|c\n")
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert not legacy.exists()
    assert "removed legacy src/modules/" in capsys.readouterr().out


@pytest.mark.parametrize("lock_text", [None, "# my own notes\n", ""])
def test_generate_keeps_src_modules_it_did_not_write(tmp_path: Path, checkout: Path, lock_text: str | None,
                                                     capsys: pytest.CaptureFixture[str]) -> None:
    p = Paths(tmp_path / "proj")
    own = p.root / "src" / "modules"
    own.mkdir(parents=True)
    (own / "Mine.h").write_text("// the owner's code\n")
    if lock_text is not None:
        (own / "modules.lock").write_text(lock_text)
    modules.generate(p, Registry.load(checkout), ["wifi"], "s", "r", "c")
    assert (own / "Mine.h").is_file()
    assert "removed legacy" not in capsys.readouterr().out


