def test_cli_list_select_generate(project: Paths, capsys: pytest.CaptureFixture[str]) -> None:
    assert main(["modules", "list"]) == 0
    out = capsys.readouterr().out
    assert "* wifi" in out and "  pins" in out
    assert main(["modules", "select", "scheduler"]) == 0
    assert 'selected = ["scheduler"]' in project.lock.read_text()
    assert (project.modules / "src" / "XeWeModules.h").read_text().count("#include") == 3
    assert project.src_modules_h.read_text().count("(os") == 3
    assert main(["modules", "select", "nope"]) == 2
    assert main(["modules", "select", "none"]) == 0
    assert "selected = []" in project.lock.read_text()
    assert "(os" not in project.src_modules_h.read_text()
    assert "#include" not in (project.modules / "src" / "XeWeModules.h").read_text()
    assert "modules: none  (build/modules, src/Modules.h)" in capsys.readouterr().out


def test_tests_layout_clean(tmp_path: Path) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules", board_tests=True)
    (checkout / "modules" / "wifi" / "tests" / "unit").mkdir()
    (checkout / "modules" / "wifi" / "tests" / "unit" / "test_wifi.py").write_text("")
    (checkout / "modules" / "wifi" / "tests" / "board" / "__pycache__").mkdir()
    assert modules.check_tests_layout(Registry.load(checkout)) == []


@pytest.mark.parametrize(("entry", "message"), [
    ("tests/test_wifi.py", "tests/test_wifi.py not allowed"),
    ("tests/host/test_x.cpp", "tests/host not allowed"),
    ("tests/conftest.py", "tests/conftest.py not allowed"),
    ("tests/board/conftest.py", "tests/board/conftest.py not allowed"),
    ("tests/unit/__init__.py", "tests/unit/__init__.py not allowed"),
    ("tests/unit", "tests/board/test_wifi.py missing"),
])
def test_tests_layout_rules(tmp_path: Path, entry: str, message: str) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules", board_tests=True)
    wifi = checkout / "modules" / "wifi"
    if message.endswith("missing"):
        (wifi / "tests" / "board" / "test_wifi.py").unlink()
    path = wifi / entry
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix:
        path.write_text("")
    else:
        path.mkdir(exist_ok=True)
    errors = [str(p) for p in modules.check_tests_layout(Registry.load(checkout)) if p.error]
    assert any(message in e and e.startswith("error: wifi:") for e in errors), errors


def test_cli_validate_checks_tests_layout(project: Paths, tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    checkout = make_modules_checkout(tmp_path / "c", "modules")
    assert main(["modules", "validate", str(checkout)]) == 1
    assert "error: wifi: tests/board/test_wifi.py missing" in capsys.readouterr().out
